{
  "units": [
    {
      "quote": "A limited-validity passport using endorsement 46 should be issued when the medical circumstance that requires eyeglasses is temporary and the applicant has urgent or emergency travel.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When the medical circumstance requiring eyeglasses is temporary and the applicant has urgent or emergency travel, a limited-validity passport using endorsement 46 should be issued."
    },
    {
      "quote": "The applicant’s expression should be natural.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "The applicant's facial expression in the photograph should be natural."
    },
    {
      "quote": "Normal, unexaggerated smiles are acceptable,",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "Normal, unexaggerated smiles are acceptable in passport photographs."
    },
    {
      "quote": "unusual expressions and squinting are not.",
      "scope_quotes": [],
      "kind": "prohibition",
      "meaning": "Unusual expressions and squinting are not acceptable in passport photographs."
    },
    {
      "quote": "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Applicants having physical or mental disabilities, such as loss of muscle control resulting from age-related degeneration or a medical condition like Bell's Palsy, may be unable to produce a natural or unexaggerated facial expression."
    },
    {
      "quote": "You may accept a photograph without a natural or unexaggerated expression in these circumstances.",
      "scope_quotes": [
        "Applicants with physical or mental disabilities, including loss of muscle control (e.g., age-related degeneration or because of a medical condition such as Bell's Palsy), may not be able to produce a natural or unexaggerated expression."
      ],
      "kind": "permission",
      "meaning": "In circumstances where applicants have physical or mental disabilities (such as loss of muscle control from age-related degeneration or medical conditions like Bell's Palsy) preventing a natural or unexaggerated expression, an adjudicator is permitted to accept a photograph without a natural or unexaggerated expression."
    },
    {
      "quote": "Both of the applicant’s eyes should also be visible and open in the photograph (see the exception for infants in 8 FAM 402.1-1).",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "Both of the applicant's eyes should be open and visible in the photograph, subject to the infant exception referenced in 8 FAM 402.1-1."
    },
    {
      "quote": "If the applicant is unable to open one or both eyes because of a medical condition, you may accept the photograph.",
      "scope_quotes": [],
      "kind": "permission",
      "meaning": "If an applicant cannot open one or both eyes due to a medical condition, the adjudicator is permitted to accept the photograph."
    },
    {
      "quote": "In rare cases, if it is unlikely that the closed eye(s) or exaggerated expression are because of a medical condition, you should request a medical statement signed by a medical professional/health practitioner.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In rare cases where it is unlikely that closed eye(s) or an exaggerated expression stem from a medical condition, the adjudicator should request a medical statement signed by a medical professional or health practitioner."
    },
    {
      "quote": "(1) Processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer applications without photographs to their supervisor for guidance on processing passport applications received without photographs;",
      "scope_quotes": [
        "a. Applications received without photographs:"
      ],
      "kind": "recommendation",
      "meaning": "When applications are received without photographs, processing and communications/customer service personnel at passport agencies/centers or consular section personnel should refer them to their supervisor for guidance on processing."
    },
    {
      "quote": "(2) You must not accept a form DS-11 or form DS-82 received without a photograph at the public counter.",
      "scope_quotes": [
        "a. Applications received without photographs:"
      ],
      "kind": "prohibition",
      "meaning": "Personnel are strictly prohibited from accepting a Form DS-11 or Form DS-82 received without a photograph at the public counter."
    },
    {
      "quote": "See 8 FAM 1001.2 regarding importing photographs for forms DS-5504;",
      "scope_quotes": [
        "a. Applications received without photographs:"
      ],
      "kind": "background",
      "meaning": "Cross-reference providing procedural guidance in 8 FAM 1001.2 concerning the importation of photographs for Form DS-5504."
    },
    {
      "quote": "(3) Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility.",
      "scope_quotes": [
        "a. Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend any Form DS-11 received from an acceptance facility without a photograph."
    },
    {
      "quote": "The applicant must re-execute the form DS-11 (see IRL 975-04); and",
      "scope_quotes": [
        "a. Applications received without photographs:",
        "(3) Passport specialists must suspend a form DS-11 received without a photograph from an acceptance facility."
      ],
      "kind": "requirement",
      "meaning": "When a Form DS-11 is suspended due to being received without a photograph from an acceptance facility, the applicant is required to re-execute Form DS-11."
    },
    {
      "quote": "(4) Passport specialists must suspend a form DS-82 or form DS-5504 received without a photograph (see IRL 1000-05 and IRL 1018-14).",
      "scope_quotes": [
        "a. Applications received without photographs:"
      ],
      "kind": "requirement",
      "meaning": "Passport specialists are required to suspend a Form DS-82 or Form DS-5504 that is received without a photograph."
    }
  ]
}
